&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Role:&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt; &lt;/strong&gt; &lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Business Partnering, Finance&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Location:&lt;/span&gt;&lt;/strong&gt; &lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Bengaluru&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:100}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
