&lt;p class=&quot;p1&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Key Traits&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul class=&quot;ul1&quot;&gt;
&lt;li class=&quot;li4&quot; style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Strong ownership and accountability&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;li5&quot; style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Process-driven with a &lt;strong&gt;zero-error mindset&lt;br&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;li5&quot; style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;High integrity and discipline&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;li6&quot; style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Comfortable working under strict controls&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p class=&quot;p8&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Performance Metrics&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul class=&quot;ul1&quot;&gt;
&lt;li class=&quot;li4&quot; style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;100% match between physical inventory and records&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;li5&quot; style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Zero undocumented inventory movement&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;li5&quot; style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Zero asset loss due to process lapses&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;li6&quot; style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Timely reconciliation and reporting&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;Our Values&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;Empathy, Trust &amp;amp; Candor&lt;/span&gt;&lt;br&gt;&lt;/strong&gt;We put ourselves in the shoes of our colleagues and customers and don’t shy away from uncomfortable conversations, instead building trust through honest and direct feedback.&lt;/p&gt;
